def transform(grid):
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    full_rows = [r for r in range(height) if len(set(grid[r])) == 1]
    full_cols = [c for c in range(width) if len({grid[r][c] for r in range(height)}) == 1]
    for r in full_rows:
        out[r] = [2] * width
    for c in full_cols:
        for r in range(height):
            out[r][c] = 2
    return out
